// Apify run'i bitti mi, basarili mi? Basarisizsa hata firlatiriz; node'un
// error output'u "Panele Hata Bildir"e bagli oldugu icin panel sebebi gorur.
const run = $input.first().json.data || $input.first().json;
const durum = run.status;

if (durum !== "SUCCEEDED") {
  const aciklama = {
    "FAILED": "Apify run'i basarisiz oldu (genelde kredi bitti ya da actor girdisi gecersiz).",
    "ABORTED": "Apify run'i iptal edildi.",
    "TIMED-OUT": "Apify run'i zaman asimina ugradi.",
    "TIMING-OUT": "Apify run'i zaman asimina ugruyor.",
    "RUNNING": "Apify run'i 10 dakikada bitmedi; tarama cok genis olabilir.",
    "READY": "Apify run'i 10 dakikadir sirada bekliyor, hic baslamadi.",
  }[durum] || ("Apify run durumu: " + durum);
  throw new Error(aciklama + " Apify konsolundan run kaydina bakabilirsiniz.");
}

return [{ json: { runId: run.id, datasetId: run.defaultDatasetId } }];

// Google Maps e-posta DONDURMEZ; e-posta ancak isletmenin web sitesinden
// cikarilabilir. Apify'in bunu yapan "scrapeContacts" secenegi UCRETLI bir
// add-on oldugu icin ayni isi ucretsiz yapiyoruz.
//
// ONEMLI: Sayfalari BU node indirmez. n8n 2.x Code node'unu ayri bir task
// runner sandbox'inda calistirir ve orada this.helpers.httpRequest sessizce
// basarisiz olur (her siteye null doner). Bu yuzden indirme isi "Siteyi
// Getir" / "Iletisim Sayfasi" HTTP node'larina birakildi; burada yalnizca
// gelen HTML metni ayristiriliyor.

const isletmeler = $("Dataset Al").all();
const anaSayfalar = $("Siteyi Getir").all();
let iletisimler = [];
try { iletisimler = $("Iletisim Sayfasi").all(); } catch (e) { iletisimler = []; }

// HTTP node basarisiz olduysa item icinde govde yerine error durur.
const govdeAl = (item) => {
  if (!item || !item.json) return "";
  const j = item.json;
  if (typeof j.data === "string") return j.data;
  if (typeof j.body === "string") return j.body;
  return "";
};

// Rol/servis kutulari ve sahte eslesmeler lead degildir.
const ELE = /(^|[._-])(no-?reply|donotreply|postmaster|abuse|mailer-daemon)|example\.(com|org|net)|sentry\.io|wixpress\.com|godaddy|\.(png|jpe?g|gif|webp|svg|css|js)$/i;

// Hazir sablon temalarindan gelen yer tutucular ("your@email.com" gibi).
// Bunlar gercek isletme adresi degildir; mail atilirsa bounce olur.
const YER_TUTUCU = /^(your|youre?mail|yourname|firstname|lastname|adiniz|ornek|test|demo|sample|deneme)@|@(email|e-?mail|domain|yourdomain|yoursite|sitename|mysite|website|test|demo|sample|ornek|sitem|siteniz|alanadi|alanadiniz|firmaniz|domainname|company|sirket).(com|net|org|tr|com\.tr)$/i;

const EPOSTA_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,24}/g;

function epostaAyikla(html) {
  const adaylar = [];
  // mailto: en guvenilir kaynak - once onu dene, sonra duz metni tara.
  for (const m of html.matchAll(/mailto:([^"'?>\s]+)/gi)) adaylar.push(m[1]);
  for (const m of html.matchAll(EPOSTA_RE)) adaylar.push(m[0]);

  for (const ham of adaylar) {
    let temiz;
    try { temiz = decodeURIComponent(ham); } catch (e) { temiz = ham; }
    temiz = temiz.trim().toLowerCase().replace(/^[.,;:<>()]+|[.,;:<>()]+$/g, "");
    if (temiz.length < 6 || temiz.length > 100) continue;
    if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,24}$/.test(temiz)) continue;
    if (ELE.test(temiz) || YER_TUTUCU.test(temiz)) continue;
    return temiz;
  }
  return null;
}

// HTTP node'lari her girdi item'i icin bir cikti item'i uretir, sira korunur;
// bu yuzden isletme ile indirilen sayfayi indeksle esliyoruz.
const sonuclar = [];
for (let i = 0; i < isletmeler.length; i++) {
  const r = isletmeler[i].json;
  if (!r || (!r.title && !r.name)) continue;   // bos dataset item'i

  const metin = govdeAl(anaSayfalar[i]) + "\n" + govdeAl(iletisimler[i]);
  sonuclar.push({ json: Object.assign({}, r, { _eposta: epostaAyikla(metin) }) });
}

// Arama hic sonuc vermediyse bos dizi DONDURMEYIZ: n8n girdisi bos olan
// node'lari atlar, boylece "Panele Bitti Bildir" hic calismaz ve panel
// sonsuza kadar "Arama suruyor" da takili kalirdi.
if (!sonuclar.length) return [{ json: { _bos: true } }];

return sonuclar;

// Site taramasindan cikan e-postalari panelin bekledigi alanlara cevirir.
const girdi = $("Girdiyi Hazirla").first().json;
const duzlestir = (v) => (Array.isArray(v) ? v[0] : v) || null;

const leads = [];
const gorulen = new Set();
const hepsi = $input.all();

for (const item of hepsi) {
  const r = item.json;
  // _eposta site taramasindan gelir; e-posta zaten Apify ciktisinda varsa
  // (ucretli scrapeContacts acikken) onu da kabul ederiz.
  const eposta = r._eposta || duzlestir(r.email || r.emails);
  if (!eposta) continue;

  const anahtar = String(eposta).toLowerCase();
  if (gorulen.has(anahtar)) continue;   // zincir subeleri ayni maili verir
  gorulen.add(anahtar);

  leads.push({
    business_name: r.title || r.name || null,
    website: r.website || r.url || null,
    email: anahtar,
    phone: r.phone || r.phoneUnformatted || null,
    address: r.address || r.fullAddress || null,
  });
}

return [{
  json: {
    campaignId: girdi.campaignId,
    callbackUrl: girdi.callbackUrl,
    statusUrl: girdi.statusUrl,
    panelKey: girdi.panelKey,
    bulunan: leads.length,
    taranan: hepsi.length,
    leads,
  },
}];

