const body = $input.first().json.body || $input.first().json;

if (!body.campaignId) throw new Error("campaignId gelmedi. Paneli kontrol edin.");
if (!body.query) throw new Error("query (arama sorgusu) gelmedi.");

// statusUrl yeni panelde gelir; eski panelde callbackUrl'den turetiriz ki
// hata bildirimi her durumda bir yere gidebilsin.
const statusUrl = body.statusUrl || String(body.callbackUrl || "").replace(
  /\/api\/leads\/import$/,
  "/api/campaigns/" + body.campaignId + "/find-leads/status"
);

return [{
  json: {
    campaignId: body.campaignId,
    topic: body.topic || "",
    query: body.query,
    location: body.location || "",
    callbackUrl: body.callbackUrl,
    statusUrl,
    panelKey: body.panelKey,
  },
}];

